 const server=createServer((req,res)=>{const send=(type,body)=>{res.writeHead(200,{'Content-Type':type,'Cache-Control':'no-store'});res.end(body)};if(req.url==='/fixture.js')return send('text/javascript',js);if(req.url==='/salon.svg')return send('image/svg+xml','<svg xmlns="http://www.w3.org/2000/svg" width="640" height="280"><rect width="640" height="280" fill="#ead2d5"/><text x="50" y="150" font-size="45" fill="#503438">LUMI · TEST IMAGE</text></svg>');if(req.url.startsWith('/api/')){res.writeHead(500);res.end('No API allowed');return}send('text/html',`<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'self' 'unsafe-inline'; style-src 'unsafe-inline'; img-src 'self' data:; connect-src 'none'"><style>body{font:16px -apple-system,sans-serif;margin:0;padding:16px;color:#172031;background:#f8fafc}*{box-sizing:border-box}header{padding:12px;background:#dbeafe;border-radius:12px}button{min-height:44px}${css}</style><div id="root"></div><script src="/fixture.js"></script><script>(${checks.toString()})();</script>`)});
 await new Promise(r=>server.listen(port,'127.0.0.1',r));return{url:`http://127.0.0.1:${server.address().port}`,close:()=>new Promise(r=>{server.closeAllConnections();server.close(r)})};
