function checks(){const sleep=ms=>new Promise(r=>setTimeout(r,ms));const wait=async(fn)=>{const end=performance.now()+2500;while(!fn()){if(performance.now()>end)throw Error('UI timeout');await sleep(20)}};const check=(ok,label)=>{if(!ok)throw Error(label);window.campaignResults.checks.push(label)};const set=async(overrides)=>{window.setSearchPreview({...window.searchPreviewState,...overrides});await sleep(60)};
 window.runCampaignChecks=async()=>{window.campaignResults={environment:'local actual React/Next Image UI; mock authority/delivery, no production',checks:[]};await wait(()=>document.querySelector('h3')?.textContent==='gel manicure');await set({query:'red nails'});await wait(()=>document.querySelector('h3')?.textContent==='red nails');check(window.deliveryCalls.at(-1).body.query==='red nails','query change refetches selection');await set({query:'delayed'});await set({query:'nails'});await sleep(800);check(document.querySelector('h3')?.textContent==='nails','stale search response cannot revive');await set({location:'Outside'});await wait(()=>!document.querySelector('h3'));check(true,'location change removes prior match');await set({location:'Milwaukee',query:'purple'});check(!document.querySelector('h3'),'zero eligible has no sponsored card');await set({query:''});await wait(()=>document.querySelector('h3')?.textContent==='Local salon');check(true,'empty query retains local selection');await set({role:'Personal',query:'nails'});await wait(()=>document.querySelector('h3')?.textContent==='nails');check(true,'role remount selects fresh');await set({role:'Owner',preview:true,id:'one'});await wait(()=>document.querySelector('dialog h3')?.textContent==='Lumi Nails');check(!document.querySelector('section'),'owner fixture excludes real distribution');const before=window.deliveryCalls.length;await sleep(1300);check(window.deliveryCalls.length===before,'preview generates no view or click request');check(document.querySelector('dialog').textContent.includes('No views are counted'),'preview clearly nonbillable');const rows=[...document.querySelectorAll('dl > div')].map(x=>x.textContent);check(rows.includes('Credits used2.4')&&rows.includes('Reserved credits remaining117.6')&&rows.includes('Valid delivery views7'),'report uses accounting units not views times rate');check(document.documentElement.scrollWidth<=innerWidth,'no horizontal overflow');window.webkit?.messageHandlers?.campaignFixture?.postMessage({stage:'pending',result:window.campaignResults});await sleep(400);await set({id:'delayed'});await set({role:'Personal',preview:false});await sleep(800);check(!document.querySelector('dialog'),'role exit unmounts pending private preview');await set({role:'Owner',preview:true,id:'error'});await wait(()=>document.querySelector('[role="alert"]'));document.querySelector('[role="alert"] button').click();await wait(()=>document.querySelector('dialog h3'));check(true,'read failure retry works');check(!document.querySelector('dialog a'),'preview has no billable click target');await set({id:'returned'});await wait(()=>document.querySelector('dl')?.textContent.includes('Credits returned96'));check(document.querySelector('dl').textContent.includes('Reserved credits remaining0'),'returned credits are not spendable campaign reserve');await set({id:'unfunded'});await wait(()=>document.querySelector('dl')?.textContent.includes('Credits used0'));check(document.querySelector('dl').textContent.includes('Reserved credits remaining0'),'unfunded budget is not reserved balance');await set({id:'one'});await wait(()=>document.querySelector('dialog img')?.complete&&document.querySelector('dialog img')?.naturalWidth>0);await sleep(250);window.campaignResults.ok=true;window.webkit?.messageHandlers?.campaignFixture?.postMessage({stage:'complete',result:window.campaignResults});return window.campaignResults};if(new URL(location.href).searchParams.get('auto')==='1')window.runCampaignChecks().catch(e=>{window.campaignResults.error=e.message;window.webkit?.messageHandlers?.campaignFixture?.postMessage({stage:'failed',result:window.campaignResults})});}
